import styled from '@emotion/styled';
import { theme } from 'theme';

export const AccordionContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
  padding: '0 24px',
});

export const AccordionItemWrapper = styled.div({
  borderBottom: '1px solid rgba(20, 20, 20, 0.12)',
});

export const AccordionTrigger = styled.button({
  height: '72px',
  width: '100%',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'space-between',
  background: 'transparent',
  border: 'none',
  cursor: 'pointer',
  textAlign: 'left',
  transition: 'color 0.2s ease',
  fontFamily: 'Barlow',
  fontWeight: '600',
  fontSize: '18px',
  padding: '0',
});

export const AccordionIcon = styled.span({
  display: 'inline-flex',
  alignItems: 'center',
  justifyContent: 'center',
  width: '16px',
  height: '16px',
  color: '#141414',
});

interface AccordionContentProps {
  $isOpen?: boolean;
}

export const AccordionContent = styled('div', {
  shouldForwardProp: (propName) => propName !== '$isOpen',
})<AccordionContentProps>(({ $isOpen = false }) => ({
  overflow: 'hidden',
  transition: 'max-height 0.3s ease, opacity 0.3s ease',
  maxHeight: $isOpen ? '2000px' : 0,
  opacity: $isOpen ? 1 : 0,
}));

export const AccordionContentInner = styled.div({
  padding: `0 0 ${theme.spacing['6']} 0`,
});
